from __future__ import annotations
import tkinter as tk
from .version import __version__

APP_NAME="MorphoLabel"
APP_FULL_NAME="Biological morphology annotation"
APP_VERSION=__version__
APP_STATUS="Release candidate"
APP_TITLE=f"{APP_NAME} — {APP_FULL_NAME} — v{APP_VERSION}"
APP_SHORT_TITLE=f"{APP_NAME} — v{APP_VERSION}"
APP_CREATOR="Oleg Artaev"
COPYRIGHT=f"© 2026 {APP_CREATOR}"
CONTACT_EMAIL="morpholabel@olegartaev.com"
PUBLIC_REPOSITORY="https://github.com/olegartaev/MorphoLabel"
LICENSE_NAME="Apache-2.0"
ICON_SOURCE_SHA256="08a59d18aa7a4198a4731040a4a6a778528762af485cea3acb8f5ec93e5a9c7b"
ICON_PNG_BASE64=""""""

def icon_image(master):
 """Return the supplied MorphoLabel icon at its native pixel size."""
 return tk.PhotoImage(master=master,data=ICON_PNG_BASE64)

def apply_window_identity(window, short=False):
 window.title(APP_SHORT_TITLE if short else APP_TITLE)
 try:
  icon=icon_image(window)
  window.iconphoto(True,icon)
  window._morpholabel_window_icon=icon
 except Exception:
  pass
